bool GameTextTable::readCSF(const char *filename)
{
    char buffer[0x2800];
    unsigned short wideBuffer[0x2800];
    File *file = TheFileSystem->openFile(filename, 0x21, 0);
    if (!file) return false;
    file->deleteOnClose();
    char *data = file->readEntireAndClose();
    unsigned int count = 0;
    CSFHeader *header = (CSFHeader *)data;
    char *cursor = data + sizeof(CSFHeader);
    if (header->id == CSF_ID) {
        m_info = new StringInfo[header->num_labels];
        while (header->num_labels--) {
            CSFLabel *label = (CSFLabel *)cursor;
            cursor += sizeof(CSFLabel);
            if (label->id != CSF_LABEL) break;
            strncpy(buffer, cursor, label->length);
            buffer[label->length] = 0;
            cursor += label->length;
            bool found = false;
            while (label->num_strings--) {
                CSFString *string = (CSFString *)cursor;
                cursor += sizeof(CSFString);
                switch (string->id) {
                case CSF_STRING:
                    if (!found) {
                        wcsncpy(wideBuffer, (unsigned short *)cursor, string->length);
                        wideBuffer[string->length] = 0;
                        cursor += string->length * 2;
                        for (unsigned short *p = wideBuffer; *p; ++p) *p = ~*p;
                        m_info[count].label.set(buffer);
                        m_info[count].text = wideBuffer;
                        ++count;
                        found = true;
                    }
                    break;
                case CSF_STRINGWITHWAVE:
                    cursor += *(int *)cursor + 4;
                    break;
                default:
                    header->num_labels = 0;
                    label->num_strings = 0;
                    break;
                }
            }
        }
        m_count = count;
    }
    delete[] data;
    return m_count > 0;
}

